import * as React from 'react';

// Arte real da marca (pasta "Vértice Criativo" no Canva da equipe), exportada com
// transparência real pelo usuário e embutida como data URI — a marca renderiza sozinha,
// sem nenhuma requisição de arquivo externo. Variantes `dark` (nome/traços em branco) são
// geradas reaproveitando as mesmas formas, recolorindo o azul-marinho para branco.
const MARK_LIGHT = 'data:image/png;base64,';
const MARK_DARK = 'data:image/png;base64,';
const LOGO_LIGHT = 'data:image/png;base64,';
const LOGO_DARK = 'data:image/png;base64,';
const STACKED_TAG_LIGHT = 'data:image/png;base64,';
const STACKED_TAG_DARK = 'data:image/png;base64,';
const STACKED_NOTAG_LIGHT = 'data:image/png;base64,';
const STACKED_NOTAG_DARK = 'data:image/png;base64,';

const ASPECT = {
  mark: 486 / 487,
  logo: 444 / 194,
  stackedTag: 398 / 424,
  stackedNoTag: 398 / 370,
};

export interface LogoMarkProps {
  /** `light` para fundos claros/brancos, `dark` para fundos escuros ou terracota. */
  tone?: 'light' | 'dark';
  /** Tamanho de exibição (largura e altura) em px. */
  size?: number;
  className?: string;
}

/** O símbolo da Vértice Criativo sozinho (sem o nome por extenso) — para espaços compactos, como a marca do `Footer`. */
export function LogoMark({ tone = 'light', size = 28, className }: LogoMarkProps) {
  const src = tone === 'dark' ? MARK_DARK : MARK_LIGHT;
  return <img src={src} alt="Vértice Criativo" height={size} width={Math.round(size * ASPECT.mark)} className={className} />;
}

export interface LogoProps {
  /** `light` (nome em azul-marinho) para fundos claros/brancos, `dark` (nome em branco) para fundos escuros ou terracota. */
  tone?: 'light' | 'dark';
  /** Altura de exibição em px. */
  height?: number;
  className?: string;
}

/** O logotipo horizontal da Vértice Criativo: símbolo + nome lado a lado, a arte oficial da marca. Para o rodapé ou cabeçalhos, prefira este; para uma capa/momento de destaque, veja `LogoStacked`. */
export function Logo({ tone = 'light', height = 40, className }: LogoProps) {
  const src = tone === 'dark' ? LOGO_DARK : LOGO_LIGHT;
  return <img src={src} alt="Vértice Criativo" height={height} width={Math.round(height * ASPECT.logo)} className={className} />;
}

export interface LogoStackedProps {
  /** `light` (nome em azul-marinho) para fundos claros/brancos, `dark` (nome em branco) para fundos escuros ou terracota. */
  tone?: 'light' | 'dark';
  /** Inclui a linha "Estratégia e Design" abaixo do nome. Padrão: `true`. */
  tagline?: boolean;
  /** Altura de exibição em px. */
  height?: number;
  className?: string;
}

/** O logotipo vertical da Vértice Criativo (símbolo sobre o nome, com a linha "Estratégia e Design" opcional) — para capas, heros e outros momentos de destaque da marca. */
export function LogoStacked({ tone = 'light', tagline = true, height = 120, className }: LogoStackedProps) {
  const src = tagline
    ? tone === 'dark'
      ? STACKED_TAG_DARK
      : STACKED_TAG_LIGHT
    : tone === 'dark'
      ? STACKED_NOTAG_DARK
      : STACKED_NOTAG_LIGHT;
  const aspect = tagline ? ASPECT.stackedTag : ASPECT.stackedNoTag;
  return <img src={src} alt="Vértice Criativo" height={height} width={Math.round(height * aspect)} className={className} />;
}
